let attractors = [];
let numAttractors = 5;
let quadtreeWidth = 1400;
let quadtreeHeight = 850;
let maxSeedsLimit = 85;

// 吸引子類別
class Attractor {
  constructor(i) {
    this.i = i;
    this.x = 0;
    this.y = 0;
  }
  update() {
    let time = frameCount * 0.006;
    // 用 Perlin 雜訊讓吸引子在 2D 空間滑行
    this.x = map(noise(this.i * 10 + time, 100), 0, 1, -quadtreeWidth / 2, quadtreeWidth / 2);
    this.y = map(noise(this.i * 10 + time, 500), 0, 1, -quadtreeHeight / 2, quadtreeHeight / 2);
  }
}

// 四叉樹節點類別
class QTNode {
  constructor(x, y, w, h, level) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.level = level;
    this.children = [];
    this.isLeaf = true;
  }

  subdivide(maxL) {
    let subdiv = false;
    if (this.level < maxL) {
      // 如果離任何一個吸引子足夠近，則向下剖分
      let cx = this.x + this.w / 2;
      let cy = this.y + this.h / 2;
      let sensitivity = 1.3 + (window.audioLow || 0.5) * 1.8;

      for (let a of attractors) {
        let d = dist(cx, cy, a.x, a.y);
        if (d < (this.w * sensitivity)) {
          subdiv = true;
          break;
        }
      }
    }

    if (subdiv) {
      this.isLeaf = false;
      let hw = this.w / 2;
      let hh = this.h / 2;
      this.children.push(new QTNode(this.x, this.y, hw, hh, this.level + 1));
      this.children.push(new QTNode(this.x + hw, this.y, hw, hh, this.level + 1));
      this.children.push(new QTNode(this.x, this.y + hh, hw, hh, this.level + 1));
      this.children.push(new QTNode(this.x + hw, this.y + hh, hw, hh, this.level + 1));

      for (let child of this.children) {
        child.subdivide(maxL);
      }
    }
  }

  collectSeeds(list) {
    if (list.length >= maxSeedsLimit) return;
    if (this.isLeaf) {
      list.push(createVector(this.x + this.w / 2, this.y + this.h / 2));
    } else {
      for (let child of this.children) {
        child.collectSeeds(list);
      }
    }
  }
}

// Sutherland-Hodgman 多邊形剪裁器
function clipPolygon(poly, m, d) {
  let clipped = [];
  if (poly.length === 0) return clipped;

  for (let i = 0; i < poly.length; i++) {
    let current = poly[i];
    let next = poly[(i + 1) % poly.length];

    // 判斷點是否在平分線內側
    let currIn = p5.Vector.sub(current, m).dot(d) <= 0;
    let nextIn = p5.Vector.sub(next, m).dot(d) <= 0;

    if (currIn) {
      clipped.push(current);
    }
    if (currIn !== nextIn) {
      let diff = p5.Vector.sub(next, current);
      let denom = diff.dot(d);
      if (abs(denom) > 0.0001) {
        let t = p5.Vector.sub(m, current).dot(d) / denom;
        let intersect = p5.Vector.add(current, p5.Vector.mult(diff, t));
        clipped.push(intersect);
      }
    }
  }
  return clipped;
}

function setup() {
  createCanvas(1280, 720, WEBGL);

  // 初始化吸引子
  for (let i = 0; i < numAttractors; i++) {
    attractors.push(new Attractor(i));
  }

  background(0);
}

function draw() {
  background(0);

  // 更新吸引子
  for (let a of attractors) {
    a.update();
  }

  // 動態調整四叉樹深度
  let beatEnergy = window.beatEnergy || 0.0;
  let maxLevel = (beatEnergy > 0.6) ? 5 : 4;

  // 重建四叉樹
  let root = new QTNode(-quadtreeWidth/2, -quadtreeHeight/2, quadtreeWidth, quadtreeHeight, 0);
  root.subdivide(maxLevel);

  // 收集葉子中心作為 Voronoi 種子點
  let seeds = [];
  root.collectSeeds(seeds);

  // 設定 3D 相機旋轉與推拉
  let time = frameCount * 0.004;
  let camRotX = sin(time * 0.8) * 0.28;
  let camRotY = cos(time * 0.6) * 0.38;
  let camZoom = 1.0 + (window.audioLow || 0.5) * 0.12 + beatEnergy * 0.22;
  let storyboardScale = (window.storyboardWeight !== undefined) ? (window.storyboardWeight / 50.0) : 1.0;

  push();
  scale(camZoom * storyboardScale);
  rotateX(camRotX);
  rotateY(camRotY);

  // 設置定向平行光以進行 Flat Shading 計算
  let lightDir = createVector(0.3, 0.45, 0.83).normalize();

  // 計算每個種子點的 Voronoi 胞體多邊形並進行 3D 渲染
  for (let i = 0; i < seeds.length; i++) {
    let s = seeds[i];

    // 初始化為一個覆蓋邊界的矩形
    let cellPoly = [
      createVector(-quadtreeWidth * 0.7, -quadtreeHeight * 0.7),
      createVector(quadtreeWidth * 0.7, -quadtreeHeight * 0.7),
      createVector(quadtreeWidth * 0.7, quadtreeHeight * 0.7),
      createVector(-quadtreeWidth * 0.7, quadtreeHeight * 0.7)
    ];

    // 尋找最近鄰種子進行剪裁以提升效能 (只剪裁最近的 11 個 neighbor)
    let neighbors = [];
    for (let j = 0; j < seeds.length; j++) {
      if (i === j) continue;
      let dSq = sq(seeds[i].x - seeds[j].x) + sq(seeds[i].y - seeds[j].y);
      neighbors.push({ idx: j, d2: dSq });
    }
    neighbors.sort((a, b) => a.d2 - b.d2);

    let clipCount = min(neighbors.length, 11);
    for (let n = 0; n < clipCount; n++) {
      let neighborSeed = seeds[neighbors[n].idx];
      let m = p5.Vector.add(s, neighborSeed).mult(0.5); // 中點
      let d = p5.Vector.sub(neighborSeed, s);          // 向量
      cellPoly = clipPolygon(cellPoly, m, d);
      if (cellPoly.length < 3) break;
    }

    if (cellPoly.length < 3) continue;

    // 胞體 Z 軸三維運動 (角錐頂點高度)
    let pulseFreq = frameCount * 0.05 + i * 0.12;
    let baseZ = -90;
    let apexZ = baseZ + (noise(s.x * 0.003, s.y * 0.003, frameCount * 0.008) - 0.45) * 220 + beatEnergy * 150 * sin(pulseFreq);

    // 決定胞體風格 (1/3 為實心灰階著色角錐，2/3 為網格線框)
    let styleIdx = i % 3;
    let apex = createVector(s.x, s.y, apexZ);

    if (styleIdx === 0) {
      // 實心晶體 flat shading
      for (let v = 0; v < cellPoly.length; v++) {
        let pCurrent = cellPoly[v];
        let pNext = cellPoly[(v + 1) % cellPoly.length];

        // 晶體三角面頂點：Apex, pCurrent, pNext
        let vA = apex;
        let vB = createVector(pCurrent.x, pCurrent.y, baseZ);
        let vC = createVector(pNext.x, pNext.y, baseZ);

        // 計算三角面法向量
        let edge1 = p5.Vector.sub(vB, vA);
        let edge2 = p5.Vector.sub(vC, vA);
        let normal = edge1.cross(edge2).normalize();

        // 光照亮度係數
        let dotProd = normal.dot(lightDir);
        let brightness = map(abs(dotProd), 0, 1, 40, 245);

        fill(brightness);
        stroke(0); // 黑色線條勾勒晶體邊界，極具科技感
        strokeWeight(1.0);

        beginShape(TRIANGLES);
        vertex(vA.x, vA.y, vA.z);
        vertex(vB.x, vB.y, vB.z);
        vertex(vC.x, vC.y, vC.z);
        endShape();
      }
    } else {
      // 網格線框風格 (白色細線框)
      stroke(240, 240, 250, 0.48); 
      strokeWeight(0.7);
      noFill();

      // 繪製底面多邊形與角錐側邊稜線
      beginShape();
      for (let pt of cellPoly) {
        vertex(pt.x, pt.y, baseZ);
      }
      endShape(CLOSE);

      for (let pt of cellPoly) {
        line(apex.x, apex.y, apex.z, pt.x, pt.y, baseZ);
      }
    }
  }

  pop();
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}

